python3 -c "import zipfile, re, xml.etree.ElementTree as ET
from collections import defaultdict
z = zipfile.ZipFile('budget.xlsx')
xml = re.sub(r' xmlns[^ ]+=\"[^\"]*\"', '', z.read('xl/worksheets/sheet1.xml').decode('utf-8'), count=1)
root = ET.fromstring(xml)
cells = {}
for row in root.iter('row'):
    for c in row.iter('c'):
        col = re.match(r'([A-Z]+)', c.get('r')).group(1)
        key = (row.get('r'), col)
        if c.find('is') is not None:
            cells[key] = ''.join(t.text or '' for t in c.iter('t'))
        else:
            v = c.find('v')
            cells[key] = v.text if v is not None and v.text else None
cats = defaultdict(float)
for r in range(11, 23):
    val = cells.get((str(r), 'C'))
    if val is not None:
        cats[cells.get((str(r), 'A'))] += float(val)
print(dict(cats))
print('TOTAL_EXPENSES =', sum(cats.values()))"
